window.kbPageData["views/entry/k-f465cc5ea9fa9db1"] = {"key":"entry/k-f465cc5ea9fa9db1","state":{"route":"entry/k-f465cc5ea9fa9db1"},"node":{"id":"k-f465cc5ea9fa9db1","mode":"k","title":"工作量与合作效率","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["恒定效率下工作量等于效率乘以时间，合做效率等于各方效率之和"],"qs":["江苏 2025 B类 行测#61"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"效率恒定时，工作量等于效率乘以时间。各方同时工作且完成量可以直接相加时，合作效率等于各方效率之和。","review":{"definition":"效率恒定时，工作量等于效率乘以时间。各方同时工作且完成量可以直接相加时，合作效率等于各方效率之和。","explanation":"设两架无人机的每小时效率分别为m、n。合做1小时后尚余三分之二，说明m+n等于总工作量的三分之一。先由M飞2小时、再由N飞5小时完成全部，故2m+5n=3(m+n)，得m=2n。取m=2、n=1，总工作量为9，M单独完成需9÷2=4.5小时。","references":[],"evidence":"两架无人机同时工作1小时后，有三分之二的农田尚未喷洒","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#61":{"paper":"江苏 2025 B类 行测","n":61,"mod":"数量关系","src":["91e0d9fd02ca7ec6d61f.pdf",12],"asrc":["f2ff67a0f2a2f7e8e926.pdf",20],"card":"391a1ae81dec6cba4d7a9713","links":[{"id":"k-f465cc5ea9fa9db1","role":"解题依据","why":"用效率乘时间表示各自完成量，并将两架无人机的完成量相加。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f465cc5ea9fa9db1":[["江苏 2025 B类 行测#61"]]}};
